def find_root() -> Path:
    here = Path(__file__).resolve().parent
    candidates = (
        Path.cwd(),
        here,
        Path.cwd() / "kalshi-qss-bot",
        here / "kalshi-qss-bot",
        here.parent / "kalshi-qss-bot",
    )
    for candidate in candidates:
        if (candidate / "qseries_v2").is_dir():
            return candidate.resolve()
    raise SystemExit("[ERROR] Could not locate kalshi-qss-bot repository.")


